# Purpose: Composition-associated variation and residualized MGS
# Manuscript/panels: Supplementary Figure 2a
# Reviewer comments: R2 Comment 3
# Execution requires the inputs and working-directory layout described in README.md; "02_Reviewer_Analyses/03_Composition_MGS_sensitivity.R"
#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(pheatmap);library(princurve)})
arg<-grep('^--file=',commandArgs(FALSE),value=TRUE);script<-normalizePath(sub('^--file=','',arg[1]));source(file.path(dirname(dirname(script)),'00_paths.R'))
OUT<-file.path(RESULT_DIR,'R2_2_composition');FIG<-file.path(FIGURE_DIR,'R2_2_composition');LOG<-file.path(LOG_DIR,'R2_2_composition');dir.create(OUT,recursive=TRUE,showWarnings=FALSE);dir.create(FIG,recursive=TRUE,showWarnings=FALSE);dir.create(LOG,recursive=TRUE,showWarnings=FALSE)
validate_revision_paths(c('BULK_STEP1_RDATA','BULK_CLUSTER_RDATA'))
req<-c(ESTIMATE_OFFICIAL_SCORES_CSV,MGS_UNBIASED_RDS,SC_PATIENT_CELLTYPE_SUMMARY_CSV);if(any(!file.exists(req)))stop('Missing R2.2 inputs: ',paste(req[!file.exists(req)],collapse='; '))
cols<-c(C1='#B05A7A',C2='#D99B3D',C3='#4C78A8');theme_set(theme_classic(base_size=9,base_family='sans'))
save_bundle<-function(p,n,w=7,h=4.5){ggsave(file.path(FIG,paste0(n,'.pdf')),p,width=w,height=h,device=pdf,family='sans');ggsave(file.path(FIG,paste0(n,'.svg')),p,width=w,height=h,device=svglite::svglite);ggsave(file.path(FIG,paste0(n,'.tiff')),p,width=w,height=h,device=ragg::agg_tiff,dpi=600,compression='lzw');ggsave(file.path(FIG,paste0(n,'_preview.png')),p,width=w,height=h,device=ragg::agg_png,dpi=300)}
le<-function(f){z<-new.env(parent=emptyenv());load(f,envir=z);z};s1<-le(BULK_STEP1_RDATA);s2<-le(BULK_CLUSTER_RDATA)
est<-read.csv(ESTIMATE_OFFICIAL_SCORES_CSV,check.names=FALSE);est$SampleID<-sub('^tpm[.]','',est$SampleID);mgs<-readRDS(MGS_UNBIASED_RDS)$mgs_unbiased;mgs$SampleID<-sub('^tpm[.]','',mgs$Sample)
ref<-setNames(as.character(s2$meta_step2$Subtype),s2$meta_step2$SampleID);ids<-names(ref);est<-est[match(ids,est$SampleID),,drop=FALSE];mgs<-mgs[match(ids,mgs$SampleID),,drop=FALSE];stopifnot(identical(est$SampleID,ids),identical(mgs$SampleID,ids),nrow(est)==38L)
df<-data.frame(SampleID=ids,Subtype=ref,MGS=as.numeric(mgs$MGS_unbiased),Stromal_Score=as.numeric(est$Stromal_Score),Immune_Score=as.numeric(est$Immune_Score),ESTIMATE_Score=as.numeric(est$ESTIMATE_Score),Tumour_Purity=as.numeric(est$Tumour_Purity))
vars<-c('Stromal_Score','Immune_Score','ESTIMATE_Score','Tumour_Purity')
sumtab<-do.call(rbind,lapply(vars,function(v){z<-df[[v]];do.call(rbind,lapply(levels(factor(df$Subtype)),function(g){x<-z[df$Subtype==g];data.frame(metric=v,Subtype=g,mean=mean(x),median=median(x),sd=sd(x),IQR=IQR(x))}))}))
kw<-do.call(rbind,lapply(vars,function(v){k<-kruskal.test(df[[v]]~df$Subtype);p<-pairwise.wilcox.test(df[[v]],df$Subtype,p.adjust.method='BH',exact=FALSE);data.frame(metric=v,n=38,kruskal_chisq=unname(k$statistic),kruskal_df=unname(k$parameter),kruskal_p=k$p.value,C1_vs_C2_q=p$p.value['C2','C1'],C1_vs_C3_q=p$p.value['C3','C1'],C2_vs_C3_q=p$p.value['C3','C2'])}))
write.csv(df,file.path(OUT,'composition_scores_by_sample.csv'),row.names=FALSE);write.csv(sumtab,file.path(OUT,'composition_subtype_summary.csv'),row.names=FALSE);write.csv(kw,file.path(OUT,'composition_subtype_statistics.csv'),row.names=FALSE)
mS<-lm(MGS~Stromal_Score,df);mI<-lm(MGS~Immune_Score,df);mJ<-lm(MGS~Stromal_Score+Immune_Score,df);rS<-summary(mS)$r.squared;rI<-summary(mI)$r.squared;rJ<-summary(mJ)$r.squared
vp<-data.frame(order=c('Stromal first','Immune increment second','Immune first','Stromal increment second','Joint model','Residual'),R2=c(rS,rJ-rS,rI,rJ-rI,rJ,1-rJ),interpretation=c('sequential association; order-dependent','increment after stromal; order-dependent','sequential association; order-dependent','increment after immune; order-dependent','joint association of official ESTIMATE components','not explained by these components'));write.csv(vp,file.path(OUT,'mgs_variance_partitioning.csv'),row.names=FALSE)
write.csv(data.frame(term=names(coef(mJ)),estimate=coef(mJ),p=summary(mJ)$coefficients[,4]),file.path(OUT,'mgs_composition_model_coefficients.csv'),row.names=FALSE)

# Expression-level sensitivity: regress each bulk gene on official Stromal and Immune scores, then refit a descriptive principal curve.
tpm<-as.matrix(s1$clean_tpm)[,ids,drop=FALSE];expr<-log2(tpm+1);design<-model.matrix(~Stromal_Score+Immune_Score,df);rexpr<-t(qr.resid(qr(design),t(expr)));anchor_genes<-c('CD2','CD3D','CD3E','CD8A','GZMA','PRF1','CTLA4','HAVCR2','LAG3','PDCD1','CD68','CD163','CD74','HLA-DRA','CCL5','CXCL9','CXCL10');aa<-intersect(anchor_genes,rownames(expr));anchor<-colMeans(expr[aa,,drop=FALSE])
fit_curve<-function(x,a){v<-apply(x,1,mad,na.rm=TRUE);g<-names(sort(v[is.finite(v)&v>0],decreasing=TRUE))[seq_len(min(3000,sum(is.finite(v)&v>0)))];pc<-prcomp(t(x[g,,drop=FALSE]),center=TRUE,scale.=TRUE);cr<-principal_curve(as.matrix(pc$x[,1:min(5,ncol(pc$x))]),smoother='smooth_spline',stretch=0);rho<-cor(cr$lambda,a,method='spearman');z<-cr$lambda;if(rho<0)z<-max(z)-z;z<-(z-min(z))/diff(range(z));names(z)<-colnames(x);list(score=z,rho=rho,genes=g,pc=pc,curve=cr)}
fr<-fit_curve(rexpr,anchor);rs<-data.frame(SampleID=ids,Subtype=df$Subtype,MGS_original=df$MGS,MGS_composition_residualized=fr$score[ids]);rs$delta<-rs$MGS_composition_residualized-rs$MGS_original;rk<-kruskal.test(MGS_composition_residualized~Subtype,rs);rp<-pairwise.wilcox.test(rs$MGS_composition_residualized,rs$Subtype,p.adjust.method='BH',exact=FALSE);rst<-data.frame(metric=c('Spearman residualized vs original','Kendall residualized vs original','Kruskal-Wallis residualized','C1_vs_C2_q','C1_vs_C3_q','C2_vs_C3_q','Principal-curve anchor rho'),value=c(cor(rs$MGS_original,rs$MGS_composition_residualized,method='spearman'),cor(rs$MGS_original,rs$MGS_composition_residualized,method='kendall'),rk$p.value,rp$p.value['C2','C1'],rp$p.value['C3','C1'],rp$p.value['C3','C2'],fr$rho));write.csv(rs,file.path(OUT,'mgs_expression_residualized_scores.csv'),row.names=FALSE);write.csv(rst,file.path(OUT,'mgs_expression_residualized_statistics.csv'),row.names=FALSE);saveRDS(list(fit=fr,design=design,anchor_genes=aa),file.path(OUT,'mgs_expression_residualized_fit.rds'))

sc<-read.csv(SC_PATIENT_CELLTYPE_SUMMARY_CSV,check.names=FALSE);scsum<-do.call(rbind,lapply(split(sc,sc$cell_type),function(z)data.frame(cell_type=unique(z$cell_type),n_patients=length(unique(z$patient)),total_cells=sum(z$n_cells,na.rm=TRUE),mean_C1=mean(z$C1_score,na.rm=TRUE),mean_C2=mean(z$C2_score,na.rm=TRUE),mean_C3=mean(z$C3_score,na.rm=TRUE))));write.csv(scsum,file.path(OUT,'singlecell_patient_celltype_summary_recomputed.csv'),row.names=FALSE)

long<-do.call(rbind,lapply(vars,function(v)data.frame(SampleID=df$SampleID,Subtype=df$Subtype,Metric=v,Score=df[[v]])));p1<-ggplot(long,aes(Subtype,Score,fill=Subtype))+geom_boxplot(width=.65,outlier.shape=NA,alpha=.75)+geom_jitter(width=.08,size=1.3)+facet_wrap(~Metric,scales='free_y',nrow=1)+scale_fill_manual(values=cols)+labs(x=NULL,y='Official ESTIMATE score')+theme_classic(base_size=8,base_family='sans')+theme(legend.position='none',strip.background=element_blank(),strip.text=element_text(face='bold'));save_bundle(p1,'R2_2_official_estimate_by_subtype',10,3.2)
rl<-rbind(data.frame(SampleID=rs$SampleID,Subtype=rs$Subtype,Metric='Original MGS',Score=rs$MGS_original),data.frame(SampleID=rs$SampleID,Subtype=rs$Subtype,Metric='Composition-residualized MGS',Score=rs$MGS_composition_residualized));p2<-ggplot(rl,aes(Subtype,Score,fill=Subtype))+geom_boxplot(width=.65,outlier.shape=NA,alpha=.75)+geom_jitter(width=.08,size=1.3)+facet_wrap(~Metric,scales='free_y')+scale_fill_manual(values=cols)+labs(x=NULL,y='MGS')+theme_classic(base_size=9,base_family='sans')+theme(legend.position='none',strip.background=element_blank(),strip.text=element_text(face='bold'));save_bundle(p2,'R2_2_mgs_composition_residual_sensitivity',7.2,3.6)
hm<-subset(scsum,n_patients>=10);mat<-as.matrix(hm[,c('mean_C1','mean_C2','mean_C3')]);rownames(mat)<-hm$cell_type;colnames(mat)<-c('C1 signature','C2 signature','C3 signature');pdf(file.path(FIG,'R2_2_singlecell_celltype_signature_heatmap.pdf'),width=5.5,height=5.5);pheatmap(mat,cluster_rows=TRUE,cluster_cols=FALSE,color=colorRampPalette(c('#F7FBFF','#6BAED6','#08306B'))(100),border_color='white',main='Patient-level public single-cell summaries');dev.off()
lines<-c(paste0('n discovery samples = ',nrow(df)),paste0('Official ESTIMATE joint R2 = ',sprintf('%.4f',rJ)),paste0('Stromal-first R2 = ',sprintf('%.4f',rS),'; Immune increment = ',sprintf('%.4f',rJ-rS)),paste0('Immune-first R2 = ',sprintf('%.4f',rI),'; Stromal increment = ',sprintf('%.4f',rJ-rI)),paste0('Joint residual = ',sprintf('%.4f',1-rJ)),paste0('Expression-residualized MGS Spearman vs original = ',sprintf('%.4f',rst$value[1]),'; KW P = ',format.pval(rk$p.value,digits=5)),paste0('Official ESTIMATE subtype KW P: stromal=',format.pval(kw$kruskal_p[kw$metric=='Stromal_Score'],digits=5),', immune=',format.pval(kw$kruskal_p[kw$metric=='Immune_Score'],digits=5),', purity=',format.pval(kw$kruskal_p[kw$metric=='Tumour_Purity'],digits=5)),'Interpretation: these are within-cohort expression associations; they do not estimate causal cellular fractions or prove tumour-cell-intrinsic states.');writeLines(lines,file.path(OUT,'R2_2_verified_summary.txt'));writeLines(capture.output(sessionInfo()),file.path(LOG,'sessionInfo.txt'));print(lines)
